const description={seclusion:'选定最多闭关多久。每月照常耗粮、修炼或静养；在后山还会采药补给。遇事件、筑元关口、断粮风险或寿元危险立即出关。',scroll:'顾闻溪带来一卷难解的道书，请你当众释义。你怎样处理其中的关键一页？',herbalist:'叶青蘅跌伤在药径旁。她识得后山隐泉，却急需一株灵草疗伤。',yeFollowup:'几个月后，你又经过这条药径。叶青蘅记得当时的选择，泉径与眼前的生计都可以再作打算。',guFollowup:'顾闻溪记得你如何处理那页残卷，邀你再辨一部旧书。',guReturn:'先前校卷或送稿的选择，换来了不同的后续。',chengFollowup:'整理旧卷之后，程上师想请你再帮一次忙。',chengReturn:'程上师记得你接过的差事，向你问起下一步。',guText:'星篆残篇有缺页。可与顾闻溪合校，也可购卷独解；此时只是立题，不会直接得法。',guFinish:'寻回缺页、养足根骨之后，试行星篆真章。若未备齐，可先离开继续准备。',yeText:'叶青蘅留下养脉纲目，你可以帮她养护泉脉，也可独自取样；两路都需采药验证。',yeFinish:'亲自采药并将身体养到能承法，才可试行青华篇。',luMeet:'陆知衡不轻售真章。你可以押资立契、替商队护送散卷、出手拦截截卷修士，或暂不介入。若交手失利，卷册受损后仍可赔付修复，继续这条人物线。',luReturn:'护卷之约将到期。可以用银钱或灵草结清，亦可卖掉手中散卷，离开这条路线。',sealAudience:'守池差事或护卷凭证可换池契。持契仍须备药，才可在善渊观取用照骨玄泉。',stoneScout:'遇见寻泉客闻秋后，可让泉、出银钱、独自探访或争夺本次优先权。胜出只降低石髓池入池所需的灵草，不会直接取得仙品华池。',mentor:'上师放下道书，看你是来求教、帮忙，还是求取更深的法门。',trueText:'你已修习导脉经多时，又替上师整理过道书。程上师取出一卷未署名的密卷，问你是否愿为他校订。',spring:'开脉用池各有代价。后山可寻瑶光或石髓池；善渊观持池契可取照骨玄泉。',manual:'新得法卷须按月参悟，参透且属性契合后才能转修；转修本身不耗月份，本层功行上限与修炼速度随功法改变。',stage:'稳固根基更慢但更稳；急进省时，却更易失利并留下暗伤。失败损失四分之一的本层功行，并留下元基裂隙；重试有降品风险，可以消耗灵草修补。',attempt:'法门、华池、根基都已备下。强求更容易冲出高品，也更容易大幅掉档，且开脉成功率更低。'};
const afterStories={
 gu:['顾闻溪的信夹在星篆残页里，纸边满是改过又划掉的字。她找到一处旧注的误读：照那一句行气，后学也许会伤到元基。你的校本已经借出，错字里也有你的笔迹。\n\n“我会把自己的名字写在勘误后面，”她说，“你的那一行，你打算怎么办？”','半年后，顾闻溪又来了一封信。校本传到了山下，读书人开始争论当时是谁先读错了那一行。她没有替你作答，只把两份旧注和一页新纸放在案上。'],
 ye:['一张沾了药汁的笺纸送到后山。叶青蘅写字很急，开头只有“药还缺两株”，末尾却仔细记了伤者的脉象。她自己背着药篓来了，见你先看药方，才抬眼问你。\n\n“这人等不得。不过你也正在养脉，别答应了又怪自己。”','数月过去，叶青蘅再见你时先看了一眼你的气色。她说起那条山径的人，随后从药篓里取出一只纸包。上回留下的选择，这一次要由你自己收尾。'],
 lu:['陆知衡送来的不是催债帖，而是一册账。你求得真章后，护卷的旧契已经结清；商队却又找出一页散在外面的余卷。他把卷目与两笔价钱摆在桌上，手指压住最末一行。\n\n“契结了，人情没结。我不替你决定这页纸该走哪条路。”','陆知衡的回信写在旧契背面，没有一句寒暄。他记清了上次的银钱、余卷和收卷人，也留下一笔账等你来定。见面时他才说：“先把事讲明，再谈交情。”'],
 cheng:['程上师在书案前翻你校过的旧卷，未立即谈真章。他指了指廊下几个初来善渊观的弟子：有人连第一口气也行不稳。\n\n“我传你法，不等于你欠我一生差事，”他说，“只是他们现在也在门外。你愿意教一程，还是取了酬劳去过自己的关？”','过了些时日，程上师又取出你当年的行气注。廊下弟子已有的各自入了门，有的仍在原处打转。他把一张旧注推给你，没有问你是否后悔，只问你这次怎么看。']
};
title.ordealHelp='问气机逆乱';description.ordealHelp='入真之后的修行碍难尚未解除。可以先查看程上师、顾闻溪或叶青蘅的帮助门槛；调查不耗月份，也不锁路线。正式受助耗时两个月并选定该路，也可暂不求助，另寻演武破碍。';
function promptTitle(s){if(s.pending==='ascension')return '五气朝元 · '+G.ascensionPreview(s)[s.mingqi.fiveQi.journey.ascension.index].name;if(s.pending==='luReturn'&&s.story.luRoute==='fightDelayed')return '陆知衡 · 修复受损散卷';if(s.pending?.startsWith('after-')){const [,who,part]=s.pending.split('-');return ({gu:'顾闻溪 · 星篆误字',ye:'叶青蘅 · 山中药笺',lu:'陆知衡 · 契外余卷',cheng:'程上师 · 传法之后'})[who]+(part==='2'?' · 回音':'');}return s.pending?.startsWith('scene-')?sceneTitle[s.pending.slice(6)]:title[s.pending];}
function promptDescription(s){if(s.pending==='ascension'){const p=G.ascensionPreview(s)[s.mingqi.fiveQi.journey.ascension.index];return p.level+'。'+p.reason+'请按真实薄弱处选择；已耗用外物不返还，亦可中止保命。';}if(s.pending==='luReturn'&&s.story.luRoute==='fightDelayed')return '护卷交手失利后，陆知衡带卷脱身，但散卷缺页。赔付银钱或灵草可以修复卷册，契约延期后仍能继续；也可卖出残卷，离开这条路。';if(s.pending?.startsWith('after-')){const [,who,part]=s.pending.split('-');return afterStories[who][Number(part)-1];}return s.pending?.startsWith('scene-')?`${sceneDescription[s.pending.slice(6)]||'山中有事发生。'}刚才的行动已经耗时一月；选择不会再耗月。`:description[s.pending];}
const intentText={strike:'试探出手 · 下一招为普通攻击',charge:'沉肩蓄势 · 本合不攻击，下合重击',burst:'蓄力重击 · 伤害更高',guard:'守住中门 · 本合护体提高',flow:'引气贯锋 · 将耗内息进招',earthWard:'磐岩镇脉 · 将护身并反击',metalFlash:'霜锋掠影 · 剑招迅疾',vinePounce:'藤影扑击 · 天赋神通将发',paperCut:'裂页断章 · 短刃直取卷册'};
function combatArtAspect(art,fallback){return art?.elements?.length||art?.polarity?art:fallback||{};}
function combatArtClass(art,fallback){const aspect=combatArtAspect(art,fallback),elements=(aspect.elements||[]).filter(k=>G.ELEMENTS[k]);return `combat-art ${elements.length===1?'combat-element-'+elements[0]:'combat-element-plain'} ${aspect.polarity==='yin'?'combat-yin':aspect.polarity==='yang'?'combat-yang':'combat-harmony'}`;}
function combatArtLabel(art,fallback){return aspectText(combatArtAspect(art,fallback));}
function combatLine(line,playerAspect,enemyAspect){return esc(line).replace(/(你以「[^」]+」|对方施展(?:天赋神通|招式)「[^」]+」|对方以「(?:寻常出手|蓄力重击)」)/g,part=>{const player=part.startsWith('你'),name=part.match(/「([^」]+)」/)?.[1],arts=player?G.TECHNIQUES:G.FOE_ARTS,art=Object.values(arts).find(a=>a.name===name);return `<span class="${combatArtClass(art,player?playerAspect:enemyAspect)}">${part}</span>`;}).replace(/(你的气血\s*−\s*\d+|对方气血\s*−\s*\d+|削去气血\s*\d+|你回生气血\s*\d+|对方回生气血\s*\d+)/g,part=>{const healing=part.includes('回生'),player=part.startsWith('你的')||part.startsWith('你回生');return `<strong class="combat-change ${healing?'combat-heal':'combat-damage'}-${player?'player':'enemy'}">${part}</strong>`;});}
function sparFighter(name,person){return `<div class="spar-fighter"><strong>${esc(name)}</strong><div class="spar-measure">气血 <b>${person.currentQi} / ${person.qi}</b></div><div class="spar-bar"><span style="width:${Math.max(0,Math.round(person.currentQi/person.qi*100))}%"></span></div><div class="spar-measure">内息 <b>${person.currentNei} / ${person.nei}</b></div><div class="spar-bar inner"><span style="width:${Math.max(0,Math.round(person.currentNei/person.nei*100))}%"></span></div><small>攻势 ${person.attack} · 护体 ${person.defense}<br>闪避 ${person.evasion} · 生机 ${person.vitality||0} · 反制 ${person.counter||0}<br>出手 ${aspectTag(person.attackAspect||person)}<br>护身 ${aspectTag(person.defenseAspect||person)}${person.gear?`<br>器物 ${esc(Object.values(person.gear).join("、"))}`:""}${person.innate?`<br>天赋 ${esc(person.innate)}`:""}</small></div>`;}
function sparPanel(s){if(s.combat){const c=s.combat;return `<span class="eyebrow">${c.storyEncounter==='luEscort'?'坊市护卷':c.storyEncounter==='springContest'?'后山争泉':c.storyEncounter==='mountainApe'?'药径遭遇':c.storyEncounter?'主线交锋':'演武切磋'} · 第 ${c.round} 合</span><h2>${esc(c.enemy.name)}</h2><div class="spar-fighters">${sparFighter(s.name,c.player)}${sparFighter(c.enemy.name,c.enemy)}</div><p class="affinity-note">你攻击对方：${esc(advantageLine(c.player.attackAspect,c.enemy))}<br>对方攻击你：${esc(advantageLine(c.enemy,c.player.defenseAspect))}</p><p class="spar-intent"><b>对手动向</b> ${G.FOE_ARTS[c.intent]?`<span class="${combatArtClass(G.FOE_ARTS[c.intent],c.enemy)}">${esc(intentText[c.intent])} · ${esc(combatArtLabel(G.FOE_ARTS[c.intent],c.enemy))}</span>`:esc(intentText[c.intent]||'正在观察你')}</p><div class="spar-actions">${G.combatOptions(s).filter(o=>!G.TECHNIQUES[o.id]).map(o=>`<button type="button" data-command="combat:${esc(o.id)}" ${o.disabled?'disabled':''}><strong>${esc(o.label)}</strong><small>${esc(o.detail)}</small></button>`).join('')}</div>${G.combatOptions(s).some(o=>G.TECHNIQUES[o.id])?`<details class="tech-menu" ${skillOpen?'open':''}><summary>施展招式 · ${G.combatOptions(s).filter(o=>G.TECHNIQUES[o.id]).length} 门</summary><div class="spar-actions">${G.combatOptions(s).filter(o=>G.TECHNIQUES[o.id]).map(o=>`<button type="button" data-command="combat:${esc(o.id)}" ${o.disabled?'disabled':''}><strong class="${combatArtClass(G.TECHNIQUES[o.id],c.player.attackAspect)}">${esc(o.label)}</strong><small>${esc(combatArtLabel(G.TECHNIQUES[o.id],c.player.attackAspect))} · ${esc(o.detail)}</small></button>`).join('')}</div></details>`:''}<div class="auto-choices"><span>${c.storyEncounter?'应对方式':'一键切磋'}</span><button type="button" data-command="combat:auto-aggressive">猛攻 · 优先出招</button><button type="button" data-command="combat:auto-steady">稳扎稳打 · 留意来招</button></div><div class="spar-history" role="log" aria-live="polite">${c.history.slice(-5).map(line=>`<p>${combatLine(line,c.player.attackAspect,c.enemy)}</p>`).join('')}</div><p class="spar-footnote">${c.storyEncounter==='luEscort'?'此战关系到陆知衡的卷册与契约，失手或撤退后仍可设法补救。':c.storyEncounter==='springContest'?'争胜只影响这次优先探查权；失手或收手后，其他泉径仍可寻找。':c.storyEncounter==='mountainApe'?'药径交手关系到采集与伤势，认输可退回药径。':c.storyEncounter?'此战会影响人物关系与后续机缘，认输可结束交锋。' :'练武坪点到即止。正式切磋结束后以一月结算调息、复盘与印证；不留暗伤，每场气血和内息重新结算。'}</p>`;}
 const p=G.combatStats(s),r=s.sparRecord?.last,kit=s.trainingGear||{},record=s.sparRecord||{};
 if(r?.storyEncounter)return `<span class="eyebrow">主线交锋 · 战斗结束</span><h2>${esc(r.opponent)} · <span class="spar-result ${r.result==='胜出'?'spar-win':r.result==='失手'?'spar-loss':'spar-other'}">${esc(r.result)}</span></h2><p class="spar-intro">自动与手动交锋使用同一套逐回合结算。战报默认收起，需要时可展开复盘。</p><details class="story-battle-report"><summary>查看战报 · ${r.rounds} 合</summary><div class="spar-history full-history">${r.history.map(line=>`<p>${combatLine(line,r.playerAspect,r.enemyAspect)}</p>`).join('')}</div></details>`;
 return `<span class="eyebrow">演武坪 · 入场前</span><h2>先看自身，再选对手</h2><p class="spar-intro">五行分别增强生机、攻势、护体、反制与闪避；阴增内息，阳增气血。正式切磋连同调息、复盘与后续印证按一月结算；不留暗伤。每名常驻对手首次战胜另有一次性奖励。</p><div class="spar-preview"><strong>你当前的身手 · ${esc(G.ITEMS.manual[s.manual].name)}</strong><p>气血 ${p.qi} · 内息 ${p.nei} · 攻势 ${p.attack} · 护体 ${p.defense} · 闪避 ${p.evasion} · 生机 ${p.vitality} · 反制 ${p.counter}</p><p class="affinity-note">出手 ${aspectTag(p.attackAspect)} · 护身 ${aspectTag(p.defenseAspect)}</p><small>借用：${esc([kit.staff?'试锋木杖':null,kit.vest?'护心藤甲':null,kit.shoes?'逐风履':null,kit.talisman?'试法铜符':null].filter(Boolean).join('、')||'无')}。入场内息随当前心神而定。</small></div><p class="spar-tally"><strong>总战绩</strong>　${(record.wins||0)+(record.losses||0)+(record.draws||0)+(record.withdrawals||0)} 战 · ${record.wins||0} 胜 · ${record.losses||0} 负 · ${record.draws||0} 平 · ${record.withdrawals||0} 次收手</p>${r?`<div class="spar-last"><span class="eyebrow">最近一战</span><h3>${esc(r.opponent)} · <span class="spar-result ${r.result==='胜出'?'spar-win':r.result==='失手'?'spar-loss':'spar-other'}">${esc(r.result)}</span></h3><details class="story-battle-report"><summary>展开战报 · ${r.rounds} 合</summary><div class="spar-history full-history">${(r.history||[]).map(line=>`<p>${combatLine(line,r.playerAspect,r.enemyAspect)}</p>`).join('')}</div></details></div>`:''}`;
}
const people={gu:{name:'顾闻溪',place:'千丈岩',role:'校卷同门',portrait:'gu',line:'一字之误，可能叫后来人多走几十年弯路。',memory:s=>s.story?.guText==='complete'?'她与你走过星篆校勘一程。':s.story?.guRoute?'她记得你们共读旧卷的那日。':'她记得初识时那页蚀文是如何处理的。'},ye:{name:'叶青蘅',place:'苍梧后山',role:'采药人',portrait:'ye',line:'药总是不够，但人也不能因为这个就不救。',memory:s=>s.story?.yeRoute==='trade'?'她记得你索酬指路，此后仍肯按规矩交易。':s.story?.yeRoute==='leave'?'她记得你绕过药径，往后各凭本事。':s.story?.yeRoute?'她记得那株分给她的药。':'你在后山与她相识。'},cheng:{name:'程上师',place:'善渊观',role:'下院上师',portrait:'cheng',line:'法不可轻传。你先说说自己读懂了什么。',memory:s=>s.story?.trueTextReady?'他已认可你的校卷之功。':s.flags.mentor?'他记得你替他整理过旧卷。':'你到书案前请教过他。'},lu:{name:'陆知衡',place:'山下集市',role:'护卷商人',portrait:'lu',line:'契书有价，答应过的事也有价。',memory:s=>s.story?.luCredential?'你们之间的护卷契已经结清。':s.story?.luBattle==='won'?'你曾在后巷替他护住散卷，他记得这份信任。':s.story?.luBattle==='lost'?'护卷失手后，你补偿修卷，仍继续履约。':s.story?.luBattle==='retreated'?'你从后巷撤退后，他仍愿意让你修复遗失的卷页。':s.story?.luRoute?'他记得你们签下的旧约。':'你们曾在集市谈过护卷。'},wen:{name:'闻秋',place:'苍梧后山',role:'寻泉客',portrait:'wen',line:'泉脉无主，先看见的人也未必守得住。',memory:s=>s.story?.stonePriority?'你们曾为石髓池的先探之权交涉或交手，他记得那次结果。':s.story?.stoneClue?'他曾与你分享或交易过石髓池的泉脉线索。':'你在后山泉径与他相识。'}};
const gearLabels={weapon:'兵器',armor:'护身',shoes:'足履',relic:'佩器'};
function bookHeading(kind,name){return `<div class="codex-title"><span class="eyebrow">${kind}</span><h2>${name}</h2></div>`;}
function realmLabel(item){return item.stageMax==null?'不限境界（无额外战斗加成）':`${G.STAGES[item.stageMin]}至${G.STAGES[item.stageMax]}（开脉前）`;}
function realmBadge(item){return `<span class="realm-badge">${item.stageMax==null?'不限境界':'开脉前适用'}</span>`;}
function equipped(s){const g=s.trainingGear||{};return {weapon:G.EQUIPMENT.weapon[g.staff?1:0],armor:G.EQUIPMENT.armor[g.vest?1:0],shoes:G.EQUIPMENT.shoes[g.shoes?1:0],relic:G.EQUIPMENT.relic[g.talisman?1:0]};}
function profile(s){const b=G.combatStats(s),eq=equipped(s),remaining=Math.max(0,s.lifeLimitMonths-s.ageMonths);return `<div class="portrait-hero"><img src="./images/seeker-${s.gender==='male'?'male':'female'}.webp" alt="${esc(s.name)}的水墨画像"><div><span class="eyebrow">苍梧人物小传</span><h2>${esc(s.name)}</h2><p>${s.gender==='male'?'男':'女'} · ${esc(G.ORIGINS[s.origin].name)} · ${esc(G.TALENTS[s.talent].name)}</p><p>${esc(G.STAGES[s.stage])} · ${esc(G.LOCATIONS[s.location].name)}</p></div></div>${statusAffinity(s)}<div class="catalog-grid"><section class="catalog-card"><h3>五维与修行</h3><dl>${[['五行本源',(s.elements||[]).map(v=>G.ELEMENTS[v]).join('、')||'素元'],['阴阳气象',G.POLARITIES[s.polarity]||'冲和'],['根骨',s.root],['悟性',s.wit],['体魄',`${G.effectiveBody(s)} / ${s.body}`],['道心',s.dao],['处世',s.social],['心神',s.focus],[s.chapter==='mingqi'?'入道初行':'本层功行',s.chapter==='mingqi'?`${s.mingqi.completed.length} / 3 项`:`${s.progress.toFixed(2)} / ${G.cap(s)}`],['累计功行',s.totalProgress.toFixed(2)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="catalog-card"><h3>岁月与身手</h3><dl>${[['年龄',`${(s.ageMonths/12).toFixed(1)} 岁`],['寿限',`${(s.lifeLimitMonths/12).toFixed(1)} 岁`],['余寿',`${(remaining/12).toFixed(1)} 年`],['暗伤',s.wounds],['元基裂隙',s.foundationStrain||0],['出手属性',aspectText(b.attackAspect)],['护身属性',aspectText(b.defenseAspect)],['气血',b.qi],['内息',b.nei],['火 · 攻势',b.attack],['土 · 护体',b.defense],['水 · 闪避',b.evasion],['木 · 生机',b.vitality],['金 · 反制',b.counter]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="catalog-card"><h3>功法与招式</h3><p>现修 ${relicValue(G.ITEMS.manual[s.manual])} ${aspectTag(G.ITEMS.manual[s.manual])} · 华池 ${s.spring?relicValue(G.ITEMS.spring[s.spring]):'未定'}</p><p>所学功法：${s.manuals.map(i=>esc(G.ITEMS.manual[i].name)).join('、')}</p><p>所学招式：${(s.knownTechniques||[]).map(id=>`${esc(G.TECHNIQUES[id]?.name||id)}（${esc(G.techniqueProgress(s,id).name)}）`).join('、')||'尚未学会；演武坪可试学'}</p><p>元基：${s.foundationGrades.map((n,i)=>`${i+1}关${['','下','中','上'][n]}品`).join('、')||'尚未筑元'}</p></section><section class="catalog-card"><h3>随身器物</h3><dl>${Object.entries(eq).map(([slot,item])=>`<div><dt>${gearLabels[slot]}</dt><dd>${esc(item.name)} ${rarityBadge(item.rarity)} ${realmBadge(item)} ${aspectTag(item)}</dd></div>`).join('')}</dl><p class="small-print">演武坪借用的器物离坪后不能再用于切磋；本章主线尚未开放战斗掉落。</p></section><section class="catalog-card"><h3>资粮与往来</h3><p>银钱 ${s.silver} · 口粮 ${s.grain} · 灵草 ${s.herbs}</p><p>${Object.entries(people).filter(([id])=>s.codex?.people?.includes(id)).map(([id,p])=>`${p.name} ${s.npcFavor[id]>=0?'+':''}${s.npcFavor[id]}`).join(' · ')||'还未结识书册中的人物'}</p></section></div>`;}
function peopleBook(s){const ids=s.codex?.people||[];return bookHeading('人物志','灵溪故人')+(ids.length?ids.filter(id=>people[id]).map(id=>{const p=people[id];return `<article class="catalog-person"><div class="npc-portrait ${p.portrait}" role="img" aria-label="${p.name}画像"></div><div><span class="eyebrow">${p.role} · ${p.place}</span><h2>${p.name} <small>往来 ${s.npcFavor[id]>=0?'+':''}${s.npcFavor[id]}</small></h2><p>“${p.line}”</p><p>${esc(p.memory(s))}</p></div></article>`}).join(''):'<div class="no-books">尚未结识人物。相逢之后，这一卷才会写下他们的姓名和旧事。</div>');}
function beastsBook(s){const ids=s.codex?.combatants||[],gearNames={weapon:'兵器',armor:'护具',shoes:'鞋履',relic:'佩器'};return bookHeading('交手见闻','山泽异闻')+(ids.length?ids.map(id=>{const foe=G.SPAR_OPPONENTS[id],record=s.codex?.combatantNotes?.[id]||{kind:foe?.kind||'human',seenArts:[],seenGear:[]};if(!foe)return '';const beast=record.kind==='beast',realm=beast?'未开脉':foe.rank==='入门'?'入门吐纳':foe.rank;const arts=(record.seenArts||[]).map(art=>G.FOE_ARTS[art]).filter(Boolean),gear=(record.seenGear||[]).map(slot=>foe.gear?.[slot]?`${gearNames[slot]||slot}：${foe.gear[slot]}`:'').filter(Boolean);return `<article class="catalog-card"><span class="eyebrow">${beast?'妖兽':'人'} · ${esc(foe.rank==='山中异兽'?'苍梧山':'苍梧演武坪')}</span><h2>${esc(foe.name)}</h2><p>境界：${esc(realm)}${beast?' · 威胁：山中异兽':` · 威胁：${esc(realm)}修士`}</p><p>${beast?'异兽习性仍待进一步查明。':'此人修行与来历尚待进一步查明。'}</p>${record.observations?.length?`<p>交手见闻：${record.observations.map(esc).join('；')}</p>`:''}${arts.length?`<p>${arts.map(art=>`${art.innate?'天赋神通':'已见招式'}：${esc(art.name)}（${esc(G.proficiencyName?G.proficiencyName(foe.artRanks?.[Object.keys(G.FOE_ARTS).find(key=>G.FOE_ARTS[key]===art)]||0):'已见')}）`).join('；')}</p>`:'<p>尚未见其施展招式或神通。</p>'}${gear.length?`<p>已见装备：${gear.map(esc).join('、')}</p>`:'<p>尚未辨明装备。</p>'}</article>`}).join(''):'<div class="no-books">尚未与人类修士或山中异兽交手。遇见之后，见闻才会逐渐补全。</div>');}
const attributeNames={root:'根骨',wit:'悟性',body:'体魄',dao:'道心'};
const manualNotes=['观中入门法，吐纳缓慢；久修可增益悟性。','青篆行气温养根骨。','导脉淬炼根骨，也磨砺道心。','太微真章洗炼形神，实修有益体魄与寿限。','星篆推演蚀文，长期实修可增益悟性。','青华法借灵草养脉，兼顾体魄、伤势与寿限。','行云法以气脉参照人脉，实修增益处世。'];
