 $('lifespan').textContent=`约余 ${(remain/12).toFixed(1)} 年`;$('ages').textContent=`${(s.ageMonths/12).toFixed(1)} / ${(s.lifeLimitMonths/12).toFixed(1)} 岁`;const urgentDeadline=s.chapter!=='mingqi'&&chapterRemain<=24;$('chapter-deadline').textContent=s.chapter==='mingqi'?'明气 · 已过仙凡之门':chapterRemain?`三十岁前开脉 · 余 ${Math.floor(chapterRemain/12)} 年 ${chapterRemain%12} 月`:'三十岁期限已至';$('chapter-deadline').classList.toggle('urgent-deadline',urgentDeadline);$('chapter-deadline').closest('.chapter-deadline-row').classList.toggle('urgent-deadline',urgentDeadline);$('life-bar').style.width=`${Math.max(0,remain/s.lifeLimitMonths*100)}%`;
 $('wounds').textContent=s.wounds;for(const k of ['silver','grain','herbs','focus'])$(`sidebar-${k}`).textContent=s[k];$('foundation-strain').textContent=s.foundationStrain||0;$('manual').innerHTML=relicValue(G.ITEMS.manual[s.manual]);$('spring').innerHTML=s.spring?relicValue(G.ITEMS.spring[s.spring]):'未定';$('foundation').textContent=`${s.foundation} / 3`;$('foundation-grades').textContent=s.foundationGrades.length?s.foundationGrades.map((g,i)=>`${i+1}关${['','下','中','上'][g]}`).join(' · '):'尚未筑元';const met=(s.codex?.people||[]).filter(id=>people[id]);$('relations-block').hidden=met.length===0;$('relations-list').innerHTML=met.map(id=>`<div><span>${esc(people[id].name)}</span><b>${s.npcFavor[id]>0?'+':''}${s.npcFavor[id]}</b></div>`).join('');
