 $('chapter-intro').hidden=s.chapter!=='mingqi'||!!s.ending;if(s.chapter==='mingqi')$('chapter-intro').innerHTML=`<span class="eyebrow">第二章 · 明气初行</span><h2>${s.mingqi.introComplete?'苍梧初行已成':'仙凡之门，已在身后'}</h2><p>${s.mingqi.introComplete?'你已辨得灵息、从容走过旧日险径，并与故人论道。接下来可观息自察五气，选择自己的调和方式。成环后可出山，到河灯市补给，再赴赤炉谷测流。':'先学观息，再到苍梧后山重走险径，回善渊观与程上师辞行。三十岁前开脉的约束已解除，无须急着再冲一关。'}</p><div class="chapter-milestones">${Object.entries(G.mingqiMilestones).map(([id,label])=>`<span>${s.mingqi.completed.includes(id)?'已成':'待行'} · ${esc(label)}</span>`).join('')}</div><p class="small-print">开脉脉象：${esc(s.openingResult.grade)} · 开脉之时的留卷已保存；身死或寿尽后可以从此重来。</p>${fiveQiPanel(s)}${journeyPanel(s)}`;
