 $('compact-date').textContent=G.time(s.month).replace('求道第','第').replace('年 · ','年');$('compact-stage').textContent=G.STAGES[s.stage];$('compact-deadline').textContent=s.chapter==='mingqi'?`余寿${(remain/12).toFixed(1)}年`:chapterRemain?`开脉余${Math.floor(chapterRemain/12)}年${chapterRemain%12}月`:'期限已至';$('compact-progress').textContent=s.chapter==='mingqi'?`${s.mingqi.completed.length}/3`:`${Math.min(s.progress,limit).toFixed(0)}/${limit}`;$('compact-progress-label').textContent=s.chapter==='mingqi'?'初行':'功行';$('compact-grain').textContent=s.grain;$('compact-focus').textContent=s.focus;$('compact-silver').textContent=s.silver;$('compact-herbs').textContent=s.herbs;
 if(lastResult){$('latest-result').hidden=false;$('latest-result').innerHTML=`<span class="eyebrow">${esc(lastResult.title)}</span>${lastResult.story?`<p class="latest-result-story">${esc(lastResult.story)}</p>`:''}${lastResult.highlights.length?`<div class="latest-result-highlights">${lastResult.highlights.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}${lastResult.resources.length?`<p class="latest-result-resources">资粮：${esc(lastResult.resources.join(' · '))}</p>`:''}<small class="latest-result-meta">${lastResult.months?`耗时 ${lastResult.months} 月`:'未耗月份'}${lastResult.stopReason?` · 停止：${esc(lastResult.stopReason)}`:''}</small>`;}else $('latest-result').hidden=true;
 $('mobile-travel-toggle').disabled=!!(s.pending||s.combat||s.ending);if($('mobile-travel-toggle').disabled)closeTravel(false);const travelHtml=G.travelChoices(s).map(v=>{const id=v.id;return `<button type="button" data-command="travel:${id}" ${v.disabled?'disabled':''}>${esc(G.REGIONS[v.region]?.name||'')} · ${esc(v.name)} · ${esc(v.detail)}</button>`;}).join('');$('mobile-travel-list').innerHTML=travelHtml;
