const tabScroll=new Map();function switchTab(next){tabScroll.set(tab,window.scrollY||0);tab=next;showTab();requestAnimationFrame(()=>window.scrollTo(0,tabScroll.get(next)||0));}
function showTab(){const collection=['people','beasts','equipment','arts','elixirs'],collectionOpen=collection.includes(tab);for(const id of ['events','profile','people','beasts','equipment','arts','elixirs','books']){const pane=$(id==='events'?'story-content':`${id}-content`),button=$(`tab-${id}`),selected=tab===id;pane.hidden=!selected;if(button){button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));}}$('collection-tabs').hidden=!collectionOpen;$('tab-collection').classList.toggle('active',collectionOpen);$('tab-collection').setAttribute('aria-pressed',String(collectionOpen));}
$('create-form').addEventListener('change',e=>{if(e.target.name!=='elements')return;const boxes=[...document.querySelectorAll('input[name="elements"]')],plain=boxes.find(b=>b.value==='plain');if(e.target===plain&&plain.checked)boxes.forEach(b=>{if(b!==plain)b.checked=false;});else if(e.target.checked)plain.checked=false;const selected=boxes.filter(b=>b.checked).map(b=>b.value);if(!G.compatibleElements(selected)){e.target.checked=false;$('affinity-help').textContent='这几行互相克制，不能同修；请选择不相克的组合。';}else $('affinity-help').textContent='单行初始 3、双行各 2；素元开局五行各 1。素元是五行最低值。';if(!boxes.some(b=>b.checked))plain.checked=true;});
$('create-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);localStorage.removeItem(G.CHECKPOINT_KEY);state=G.create({name:d.get('name'),origin:d.get('origin'),talent:d.get('talent'),gender:d.get('gender'),elements:d.getAll('elements'),polarity:d.get('polarity')});lastResult=null;tab='events';save();draw();window.scrollTo(0,0);});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.tech-menu'))skillOpen=e.target.open;if(e.target.matches?.('.action-group')){const key=e.target.dataset.actionGroup;if(e.target.open)openActionGroups.add(key);else openActionGroups.delete(key);}},true);function closeTravel(restoreFocus=true){$('mobile-travel-list').hidden=true;$('mobile-travel-toggle').setAttribute('aria-expanded','false');if(restoreFocus)$('mobile-travel-toggle').focus({preventScroll:true});}
function sameCommandButton(command){return [...$('story-content').querySelectorAll('[data-command]')].find(el=>el.dataset.command===command&&!el.disabled&&el.getClientRects().length);}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-command]');
 if(b&&!b.disabled&&state){
  const hadPending=!!state.pending,command=b.dataset.command,choice=command.startsWith('choice:'),before=uiSnapshot(state),anchor=b.getBoundingClientRect().top;
  const option=choice?G.options(state).find(o=>o.id===command.slice(7)):command.startsWith('action:')?G.available(state).find(o=>o.id===command.slice(7)):null;
  const label=option?.label||b.textContent.trim().split('\n')[0];
  state=G.step(state,command);const nextResult=resultSummary(before,uiSnapshot(state),command,label);if(nextResult)lastResult=nextResult;
  const appeared=!hadPending&&!!state.pending,resolved=hadPending&&!state.pending;
  save();if(command.startsWith('travel:'))closeTravel(false);draw();
  requestAnimationFrame(()=>{
   if(appeared){$('event-prompt').focus({preventScroll:true});$('event-prompt').scrollIntoView({block:'start',behavior:'smooth'});}
   else if(resolved){$('mobile-action-heading').focus({preventScroll:true});$('mobile-action-heading').scrollIntoView({block:'nearest'});}
   else if(!choice&&!state.pending&&!state.combat&&!state.ending){const next=sameCommandButton(command);if(next){next.focus({preventScroll:true});const delta=next.getBoundingClientRect().top-anchor;if(Math.abs(delta)>24)window.scrollBy(0,delta);}}
  });
 }
 if(e.target.id==='checkpoint-restore')$('checkpoint-dialog').showModal();if(e.target.id==='event-retry')window.location.reload();if(e.target.id==='ending-book')switchTab('books');if(e.target.id==='mobile-restart')$('restart-dialog').showModal();
 if(e.target.id==='history-more'&&state){$('history-dialog-content').innerHTML=state.logs.filter(x=>!x.batch).slice().reverse().map(e=>`<article class="entry ${['突破','结局','开脉','闭关','采药'].includes(e.tag)?'important':''}"><span>${esc(G.time(e.month))} · ${esc(e.tag)}</span><p>${esc(e.text)}</p>${e.effect?`<small>${esc(e.effect)}</small>`:''}</article>`).join('');$('history-dialog').showModal();}
});
for(const id of ['events','profile','people','beasts','equipment','arts','elixirs','books'])$(`tab-${id}`).addEventListener('click',()=>switchTab(id));$('tab-collection').addEventListener('click',()=>switchTab('people'));$('mobile-travel-toggle').setAttribute('aria-expanded','false');$('mobile-travel-toggle').addEventListener('click',()=>{const open=$('mobile-travel-list').hidden;$('mobile-travel-list').hidden=!open;$('mobile-travel-toggle').setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('mobile-travel-list').hidden)closeTravel();});
